import {
  BadRequestException,
  Body,
  Controller,
  Get,
  Post,
  UploadedFile,
  UseInterceptors,
} from '@nestjs/common';
import { FileManagerService } from './file-manager.service';
import { FileInterceptor } from '@nestjs/platform-express';
import { UploadFileDto } from './dto/upload-file.dto';
import { MessagePattern, Payload } from '@nestjs/microservices';
import type { RmqFilePayload } from './types/rmq-payload.interface';

@Controller()
export class FileManagerController {
  constructor(private readonly fileManagerService: FileManagerService) {}

  @MessagePattern('test_file_manager')
  testFileManager() {
    return { message: 'File Manager is operational' };
  }

  @MessagePattern('upload_file')
  async handleUploadFile(@Payload() data: RmqFilePayload) {
    console.log('Received upload_file message with metadata:', {
      originalname: data.originalname,
      mimetype: data.mimetype,
      folder: data.folder,
    });

    // Construct a pseudo-file object for the service
    const rawBuffer = (data.buffer as any)?.data || data.buffer;
    const buffer = Buffer.isBuffer(rawBuffer)
      ? rawBuffer
      : Buffer.from(rawBuffer);

    const file = {
      buffer: buffer,
      originalname: data.originalname,
      mimetype: data.mimetype,
      size: data.size,
    } as Express.Multer.File;

    return this.fileManagerService.uploadFile(
      file,
      file.originalname,
      data.folder,
    );
  }

  @Get('test')
  testEndpoint() {
    return { message: 'File Manager is up and running!' };
  }

  @Post('upload')
  @UseInterceptors(FileInterceptor('file'))
  async uploadFile(
    @UploadedFile() file: Express.Multer.File,
    @Body() uploadFileDto: UploadFileDto,
  ) {
    if (!file) {
      throw new BadRequestException('No file provided');
    }

    return this.fileManagerService.uploadFile(
      file,
      uploadFileDto.filename,
      uploadFileDto.folder,
      {
        originalName: file.originalname,
        uploadedBy: 'user-id-example',
        ...(uploadFileDto.tags && {
          tags: uploadFileDto.tags.join(','),
        }),
      },
    );
  }
}

import { PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { BadRequestException, Injectable } from '@nestjs/common';
import { AwsConfigService } from './config/aws.config';
import { ConfigService } from '@nestjs/config';
import { UploadResponse } from './types/file.interface';
import { Readable } from 'stream';

@Injectable()
export class FileManagerService {
  private s3Client: S3Client;

  constructor(
    private awsConfig: AwsConfigService,
    private configService: ConfigService,
  ) {
    this.s3Client = new S3Client(this.awsConfig.createS3Config());
    console.log(
      'S3 Client initialized with config:',
      this.awsConfig.createS3Config(),
    );
  }

  async uploadFile(
    file: Express.Multer.File,
    filename: string,
    folder?: string,
    metadata?: Record<string, any>,
  ): Promise<UploadResponse> {
    try {
      const key = this.generateFileKey(filename, folder);
      this.validateFileType(file.mimetype);

      console.log('Uploading file ', filename);

      const buffer = Buffer.isBuffer(file.buffer)
        ? file.buffer
        : Buffer.from(file.buffer);

      const command = new PutObjectCommand({
        Bucket: this.awsConfig.getS3Bucket(),
        Key: key,
        Body: buffer,
        ContentType: file.mimetype,
        ContentLength: buffer.length,
        Metadata: metadata,
        // ChecksumAlgorithm: undefined,
        // ServerSideEncryption: 'AES256',
      });

      const result = await this.s3Client.send(command);
      return {
        key,
        url: `${this.awsConfig.getCloudfrontUrl()}${key}`,
        etag: result.ETag || '',
        versionId: result.VersionId,
      };
    } catch (error) {
      console.error('Error uploading file:', error);
      throw new BadRequestException(`File upload failed`);
    }
  }

  private generateFileKey(fileName: string, folder?: string): string {
    const timestamp = Date.now();
    const safeName = fileName.replace(/[^a-zA-Z0-9.-]/g, '_');
    const prefix = folder ? `${folder}/` : 'uploads/';
    return `${prefix}${timestamp}-${safeName}`;
  }
  private validateFileType(mimeType: string): void {
    const allowedTypes = this.configService.get('app.allowedMimeTypes');
    if (!allowedTypes.includes(mimeType)) {
      throw new BadRequestException(`File type ${mimeType} is not allowed`);
    }
  }

  private getContentTypeFromKey(key: string): string {
    const extension = key.split('.').pop()?.toLowerCase();
    const mimeTypes: { [key: string]: string } = {
      jpg: 'image/jpeg',
      jpeg: 'image/jpeg',
      png: 'image/png',
      gif: 'image/gif',
      pdf: 'application/pdf',
      txt: 'text/plain',
      json: 'application/json',
    };
    return extension
      ? mimeTypes[extension] || 'application/octet-stream'
      : 'application/octet-stream';
  }
}

