  @Prop()
  description: string;

  @Prop()
  image: string;

  @Prop({ required: true })
  price: number;

  @Prop({ required: true })
  quantity: number;

  @Prop()
  brand: string;

  @Prop({ type: [Types.ObjectId], ref: 'Category', default: [], index: true })
  category: Types.ObjectId[];

  @Prop({ unique: true, required: true })
  serialNumber: string;

  @Prop()
  characteristic: string;

  @Prop()
  reduction: number;

  @Prop()
